lynx.script:
lynx.getEngine().addEventListener('__RenderPage', function renderPage() {
  const page = __CreatePage('card', 0);
  const editor = __CreateView(0);
  __SetClasses(editor, 'editor');
  __SetAttribute(editor, 'contenteditable', 'true');
  __AppendElement(page, editor);
  globalThis.held = [page, editor];
  const names = [
    'focus', 'blur', 'keydown', 'beforeinput', 'input',
    'compositionstart', 'compositionupdate', 'compositionend',
  ];
  for (const name of names) {
    __AddEventListener(editor, name, function log(event) {
      const parts = [event.type];
      if (event.key !== undefined) parts.push(JSON.stringify(event.key));
      if (event.inputType !== undefined) parts.push(event.inputType);
      if (event.data !== undefined) parts.push(JSON.stringify(event.data));
      console.log('editing: ' + parts.join(' '));
    }, {});
  }
  __FlushElementTree();
});
